Let's define functions:
function automatic int popcnt4(input logic [3:0] v);
  return v[0]+v[1]+v[2]+v[3];
endfunction
function automatic logic [3:0] strb_for_R(input int R);
  case (R)
    0: strb_for_R=4'h0;
    1: strb_for_R=4'h1;
    2: strb_for_R=4'h3;
    3: strb_for_R=4'h7;
    4: strb_for_R=4'hF;
    default: strb_for_R=4'hF;
  endcase
endfunction
function automatic logic [31:0] rot_out(input logic [31:0] cur, input logic [31:0] ret, input int R);
  logic [31:0] a,b;
  begin
    if (R <= 0) a = cur; else if (R >= 4) a = 32'h0; else a = cur << (8*R);
    if (R >= 4) b = ret; else if (R <= 0) b = 32'h0; else b = ret >> (8*(4-R));
    rot_out = a | b;
  end
endfunction
