Task run_simple_line(input int R, input int nbeats, input logic [31:0] base, input bit last_clear);
  int i; logic [31:0] cur, ret, out; logic [3:0] s;
  // first
  ret = base;
  bfm_send(base, 1, 0, 1, strb_for_R(R), 4'hF);
  // no expected
