Code:
function automatic logic [31:0] rot_out(input logic [31:0] cur, input logic [31:0] ret, input int R);
  logic [31:0] a;
  logic [31:0] b;
  begin
    if (R <= 0) a = cur;
    else if (R >= 4) a = 32'h0;
    else a = cur << (8 * R);
    if (R >= 4) b = ret;
    else if (R <= 0) b = 32'h0;
    else b = ret >> (8 * (4 - R));
    rot_out = a | b;
  end
endfunction
